import hashlib

def shard_index(key: str, num_shards: int) -> int:
    return int(hashlib.sha1(key.encode()).hexdigest(), 16) % num_shards

import random

def backoff_delay(attempt: int) -> float:
    return min(2 ** attempt, 60) + random.uniform(0.0, 1.0)
